declare(strict_types=1); require_once __DIR__.'/../shared/response.php'; require_once __DIR__.'/../shared/request.php'; require_once __DIR__.'/../shared/auth.php'; methodOnly('PUT'); requireAdmin(); safeApi(function():void{$db=apiDatabase();$id=requestId();$i=jsonRequest();$sets=[];$p=[':id'=>$id];foreach(['name','email','phone','subject','message','status'] as $f){if(array_key_exists($f,$i)){$sets[]="$f=:$f";$p[":$f"]=$i[$f];}}if(!$sets)jsonResponse(false,'No fields to update.',null,[],422);$s=$db->prepare('UPDATE enquiries SET '.implode(',',$sets).' WHERE id=:id');$s->execute($p);if(!$s->rowCount())jsonResponse(false,'Enquiry not found or unchanged.',null,[],404);jsonResponse(true,'Enquiry updated successfully.');});
